    try{
      const data=await fetchJSON(url,15000);
      if(data?.code==='Ok'&&data.routes?.[0])return data.routes[0];
      errors.push(data?.message||data?.code||'Servidor sem cálculo');
    }catch(e){errors.push(e?.message||String(e))}
