async function importBackupFile(file){if(!file)return;let backup;try{backup=RotaMotoBackupFormat.normalize(JSON.parse(await file.text()),'motoboy',RotaMotoStorageSchema.stores)}catch(error){toast('Backup inválido ou incompatível com o Rota Moto.','error');return}modal('Mesclar backup Local-First?','Registros com chave já existente serão mantidos; apenas chaves ausentes serão acrescentadas. Outbox pendente, conflitos e dados atuais não serão substituídos. O arquivo pode conter dados pessoais, GPS e mídia; mantenha-o protegido.',[{label:'Cancelar'},{label:'Mesclar sem sobrescrever',primary:true,onClick:async()=>{try{const names=RotaMotoStorageSchema.stores,connection=await openDB(),added=await new Promise((resolve,reject)=>{const transaction=connection.transaction(names,'readwrite'),counts={added:0,kept:0};for(const name of names){const store=transaction.objectStore(name),request=store.getAll();request.onsuccess=()=>{const keyOf=row=>name==='meta'?row.key:row.id,existing=new Set(request.result.map(keyOf));for(const row of backup.stores[name]||[]){const key=keyOf(row);if(existing.has(key)){counts.kept++;continue}existing.add(key);store.put(row);counts.added++}};request.onerror=()=>reject(request.error)}transaction.oncomplete=()=>resolve(counts);transaction.onerror=()=>reject(transaction.error||new Error('Falha ao mesclar backup.'));transaction.onabort=()=>reject(transaction.error||new Error('Mesclagem do backup cancelada.'))});await loadDB();optimizedOrder=[];renderAll();toast(`Backup mesclado: ${added.added} registro(s) incluído(s); ${added.kept} preservado(s).`)}catch(error){console.error('backup merge failed',error);toast('Não foi possível mesclar o backup. Os dados atuais foram preservados.','error')}}}])}
